INSERT INTO document_types (name, description, created_at, updated_at) VALUES
  ( 'Surat Keputusan', 'Ketetapan tertulis tertinggi di tingkat rumah sakit yang disahkan oleh Direktur atau Pemilik RS sebagai dasar hukum operasional.', NOW(),NOW()),
  ( 'Pedoman', 'Ketentuan dasar yang memberikan arah dan batasan secara makro untuk penyelenggaraan suatu unit pelayanan atau pengorganisasian.', NOW(), NOW()),
  ( 'Panduan', 'Petunjuk pelaksanaan teknis yang lebih spesifik dan terfokus pada satu kegiatan atau prosedur tertentu.',  NOW(), NOW()),
  ( 'Standar Prosedur Operasional ','Instruksi kerja berupa langkah-langkah teknis yang berurutan untuk menyelesaikan suatu proses atau tindakan spesifik.',   NOW(), NOW()),
  ( 'Program', 'Dokumen perencanaan kegiatan terstruktur (biasanya tahunan) yang memiliki tujuan, target sasaran, jadwal, anggaran, dan mekanisme evaluasi.',  NOW(), NOW()),
  ( 'Peraturan Internal','Dokumen tata kelola internal rumah sakit, yang terdiri dari Hospital Bylaws (tata kelola korporat) dan Medical Staff Bylaws (tata kelola klinis).',  NOW(), NOW()),
  ( 'Kerangka Acuan Kegiatan','Dokumen perencanaan rinci yang menjelaskan latar belakang, tujuan, sasaran, dan metode pelaksanaan untuk satu kegiatan khusus atau pelatihan.',  NOW(), NOW()),
  ( 'Undangan','Surat atau bukti pemanggilan resmi kepada pihak terkait untuk menghadiri pertemuan, rapat, atau pelatihan.',  NOW(), NOW()),
  ( 'Daftar Hadir','Bukti presensi tertulis (tanda tangan) dari peserta yang hadir mengikuti suatu rapat, orientasi, atau pelatihan.',  NOW(), NOW()),
  ( 'Notulen','Catatan resmi yang mendokumentasikan jalannya rapat, topik yang dibahas, kesimpulan yang disepakati, serta rencana tindak lanjut.',  NOW(), NOW()),
  ( 'Materi','Dokumen pendukung berupa bahan presentasi (PPT), modul, leaflet, brosur, atau poster yang digunakan untuk rapat, pelatihan staf, atau edukasi pasien.',  NOW(), NOW()),
  ( 'Laporan','Dokumen tertulis yang berisi hasil pelaksanaan kegiatan, evaluasi kinerja, atau pencapaian data (contoh: Laporan Bulanan Unit, Laporan Pelatihan, Laporan Indikator Mutu).',  NOW(), NOW()),
  ( 'Sertifikat','Bukti legalitas, kualifikasi, dan kompetensi staf (contoh: Ijazah, STR, SIP, Surat Penugasan Klinis/SPK, dan Sertifikat Pelatihan).',  NOW(), NOW()),
  ( 'Dokumen Kontrak','Dokumen perjanjian kerja sama resmi secara hukum antara pihak rumah sakit dengan pihak ketiga atau vendor eksternal.',  NOW(), NOW()),
  ( 'Formulir',' Lembar kerja, lembar observasi, atau rekam jejak asuhan klinis yang sudah diisi sebagai bukti pelayanan (untuk bukti akreditasi, data identitas pasien biasanya disensor/dianonimkan).',  NOW(), NOW()),
  ( 'Dokumentasi Visual', 'Bukti fisik berupa foto dari pelaksanaan suatu kegiatan, rapat, peragaan/simulasi, atau kondisi fasilitas bangunan rumah sakit.',  NOW(), NOW());
