  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 1' LIMIT 1), 'TKRS 1.a', 'Representasi pemilik/Dewan Pengawas dipilih dan ditetapkan oleh Pemilik.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 1' LIMIT 1), 'TKRS 1.b', 'Tanggung jawab dan wewenang representasi pemilik/Dewan Pengawas meliputi poin a) sampai dengan i) yang tertera di dalam maksud dan tujuan serta dijelaskan di dalam peraturan internal rumah sakit.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 1' LIMIT 1), 'TKRS 1.c', 'Representasi pemilik/Dewan Pengawas di evaluasi oleh pemilik setiap tahun dan hasil evaluasinya didokumentasikan.', NOW(), NOW()),
