  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 2' LIMIT 1), 'TKRS 2.a', 'Telah menetapkan regulasi tentang kualifikasi Direktur, uraian tugas, tanggung jawab dan wewenang sesuai dengan persyaratan dan peraturan perundang-undangan yang berlaku.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 2' LIMIT 1), 'TKRS 2.b', 'Direktur menjalankan operasional rumah sakit sesuai tanggung jawabnya yang meliputi namun tidak terbatas pada poin a) sampai dengan i) dalam maksud dan tujuan yang dituangkan dalam uraian tugasnya.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 2' LIMIT 1), 'TKRS 2.e', 'Memiliki bukti tertulis tanggung jawab Direktur telah dilaksanakan dan dievaluasi oleh pemilik/representasi pemilik setiap tahun dan hasil evaluasinya didokumentasikan.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 3' LIMIT 1), 'TKRS 3.a', 'Direktur menunjuk pimpinan rumah sakit lain dan kepala unit sesuai kualifikasi dalam persyaratan jabatan yang telah ditetapkan beserta uraian tugasnya.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 3' LIMIT 1), 'TKRS 3.b', 'Pimpinan rumah sakit bertanggung jawab untuk melaksanakan misi yang telah ditetapkan dan memastikan kebijakan serta prosedur dilaksanakan.', NOW(), NOW()),
