  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 3.1' LIMIT 1), 'TKRS 3.1.a', 'Pimpinan rumah sakit memastikan bahwa terdapat proses untuk menyampaikan informasi dalam lingkungan rumah sakit secara akurat dan tepat waktu.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 3.1' LIMIT 1), 'TKRS 3.1.b', 'Pimpinan rumah sakit memastikan bahwa komunikasi yang efektif antara unit klinis dan nonklinis, PPA, manajemen, pasien, keluarga, dan staf telah dilaksanakan.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 3.1' LIMIT 1), 'TKRS 3.1.c', 'Pimpinan rumah sakit telah mengkomunikasikan visi, misi, tujuan, rencana strategis dan kebijakan, rumah sakit kepada semua staf.', NOW(), NOW()),
  ((SELECT standard_id FROM standard WHERE standard_code = 'TKRS 4' LIMIT 1), 'TKRS 4.a', 'Pimpinan rumah sakit berpartisipasi dalam merencanakan mengembangkan dan menerapkan program peningkatan mutu dan keselamatan pasien di lingkungan rumah sakit.', NOW(), NOW()),
